use vstd::prelude::*;

verus! {

/// Returns the zero‐based index of the last (rightmost) occurrence of the maximum value in a non‐empty slice.
/// 
/// Specifications:
/// * The input slice `v` has positive length.
/// * The returned index `i` is within bounds: `i < v.len()`.
/// * For every `j < v.len()`, `v[j] <= v[i]`.
/// * For every `k` strictly to the right of `i`, `v[k] < v[i]`.
fn mlast_maximum(v: &[i32]) -> (i: usize)
    requires
        v.len() > 0,
    ensures
        i < v.len(),
        forall j: usize :: j < v.len() ==> v[j] <= v[i],
        forall k: usize :: (i < k && k < v.len()) ==> v[k] < v[i],
{
    let mut idx: usize = 0;       // current rightmost maximum index in the prefix [0..j)
    let mut j: usize   = 1;       // we will scan positions 1..v.len()-1

    // Loop over j = 1 .. v.len(), maintaining invariants about the prefix [0..j)
    while j < v.len()
        invariant
            // j is within [1..v.len()]
            j <= v.len(),
            // idx is always a valid index in [0..j)
            idx < j,
            // in the prefix [0..j), v[idx] is a maximum
            forall p: usize :: p < j ==> v[p] <= v[idx],
            // and among those equal to v[idx], idx is the rightmost
            forall p: usize :: (p < j && v[p] == v[idx]) ==> p <= idx,
        decreases
            v.len() - j
    {
        // If the current element is at least as large as the current max,
        // update idx so that we keep the rightmost max.
        if v[j] >= v[idx] {
            // from v[j] >= v[idx] and forall p<j: v[p] <= v[idx],
            // we get forall p<j: v[p] <= v[j], so the new prefix‐maximum property holds
            assert(v[idx] <= v[j]);
            idx = j;
        } else {
            // v[j] < v[idx], so the old max remains a maximum in [0..j]
            assert(v[j] < v[idx]);
        }
        j = j + 1;
    }

    // At exit, j == v.len(), so idx is the rightmost max over the entire array.
    idx
}

}

fn main() {
    // Example usage:
    let a = vec![3, 1, 4, 4, 2];
    let i = mlast_maximum(&a);
    // i == 3, since a[3] is the last occurrence of the maximum value 4.
    assert!(i == 3);
}